'use strict';
(function(){
let frame=0,tutorialFrame=0;
function showScreen(container,c,i){InkGuideRender.renderExample(container,c,i)}
function restore(){const migrated=readLocal('inkfang-defaults-version',0)!==DEFAULTS_VERSION;const saved=migrated?DEFAULT_SETUP:readLocal('inkfang-last-setup',DEFAULT_SETUP);applySetup({...DEFAULT_SETUP,...saved},$('setupForm'));saveLocal('inkfang-defaults-version',DEFAULTS_VERSION);saveLocal('inkfang-last-setup',currentSetup());$('savedSetupNote').textContent=migrated?'Numbers · Type · Steady · Endless. Ready when you are.':'Your last choices are ready. Start again in one click.';}

function refresh(reset=false){setupChanges();const c=currentSetup();if(reset)frame=0;const page=InkOnboarding.guidePages(c)[frame];$('guideMode').textContent=`${skillNames[c.skill].toUpperCase()} / ${c.control.toUpperCase()}`;$('guideHero').innerHTML=c.control==='voice'?'YOUR VOICE.<br><em>THEIR PROBLEM.</em>':'HOLD THE<br><em>INKLANDS.</em>';$('guideIntro').textContent='Small spells. Bigger monsters. Keep the line alive.';showScreen($('guideScreen'),c,frame);$('guideFrameNumber').textContent=`0${frame+1} / 03`;$('guideFrameTitle').textContent=page.title;$('guideFrameText').textContent=page.text;$('guidePrev').disabled=frame===0;$('guideNext').disabled=frame===2;$('guideDots').replaceChildren(...[0,1,2].map(i=>{const b=document.createElement('button');b.type='button';b.textContent=String(i+1);b.setAttribute('aria-label',`Example ${i+1}`);b.setAttribute('aria-current',i===frame?'step':'false');b.onclick=()=>{frame=i;refresh()};return b}));if(status==='setup'){$('setupStatus').textContent=`Two hearts · Skills charge with correct kills · ${c.music?'Music on':'Music muted'}.`}$('startBtn').textContent='Play now ↗';$('quickRunSummary').textContent=`${c.personalOnly&&['numbers','words','spelling','mixed'].includes(c.skill)?'My list':skillNames[c.skill]} · ${c.control==='voice'?'Speak':'Type'} · ${SPEEDS[c.speed].name} · ${c.duration?c.duration/60+' min':'Endless'}`;const pace=paceFor(c.speed,c.control);$('speedNote').textContent=`${pace.name}: about ${pace.spawn} seconds between arrivals. ${c.control==='voice'?'Speaking gets a smaller, slower swarm. ':''}Every 20-second wave adds pressure; tougher monsters unlock as you survive.`;}
function tutorial(){const c=currentSetup(),p=InkOnboarding.guidePages(c)[tutorialFrame];showScreen($('tutorialScreen'),c,tutorialFrame);$('tutorialMode').textContent=`${skillNames[c.skill].toUpperCase()} / ${c.control.toUpperCase()} · OPTIONAL GUIDE`;$('tutorialCount').textContent=`0${tutorialFrame+1} / 03`;$('tutorialTitle').textContent=p.title;$('tutorialText').textContent=p.text;$('tutorialBack').disabled=tutorialFrame===0;$('tutorialNext').textContent=tutorialFrame===2?'Done · back to play →':'Next →';}
$('setupForm').onsubmit=e=>{e.preventDefault();startRun()};$('setupForm').addEventListener('change',()=>{saveLocal('inkfang-last-setup',currentSetup());refresh(true)});
$('guidePrev').onclick=()=>{frame=Math.max(0,frame-1);refresh()};$('guideNext').onclick=()=>{frame=Math.min(2,frame+1);refresh()};$('replayTutorial').onclick=()=>{stopMicCheck();tutorialFrame=0;tutorial();$('tutorialDialog').showModal()};$('tutorialBack').onclick=()=>{tutorialFrame=Math.max(0,tutorialFrame-1);tutorial()};$('tutorialNext').onclick=()=>{if(tutorialFrame<2){tutorialFrame++;tutorial()}else{$('tutorialDialog').close();saveLocal(InkOnboarding.tutorialKey(currentSetup()),true)}};$('tutorialClose').onclick=()=>$('tutorialDialog').close();
$('resetDefaults').onclick=()=>{stopMicCheck();applySetup(DEFAULT_SETUP,$('setupForm'));saveLocal('inkfang-last-setup',currentSetup());$('savedSetupNote').textContent='Numbers · Type · Steady · Endless. Ready when you are.';refresh(true)};window.InkGuide={refresh,requestStart:startRun};restore();refresh(true);
})();
